-- ========================================================


function DreamSpace_StartStory:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求

    self.isInit = false

end


function DreamSpace_StartStory:__delete()
    self.co = nil
end



function DreamSpace_StartStory:Awake()
    KTool.SetActive(self.controller.gameObject, true);
end

function DreamSpace_StartStory:Start()
    KTool.SetActive(self.controller.gameObject, true);

    -- -- 准备好目标 canvas:

    assert( self.electricalTrigger_1 )
    assert( self.electricalTrigger_2 )
    assert( self.vcam_1 )
    assert( self.vcam_2 )

    assert( self.timelineController_1BH and self.timelineController_2BH )
    self.timelineController_1 = DreamSpaceLuaUtils.GetLuaScr(self.timelineController_1BH.gameObject, "Game.DreamSpace.TimelineControll.TimelineController" )
    self.timelineController_2 = DreamSpaceLuaUtils.GetLuaScr(self.timelineController_2BH.gameObject, "Game.DreamSpace.TimelineControll.TimelineController" )

    self.isTimeline_1_End = false
    self.isTimeline_2_End = false


    self.timelineController_1.OnTimelineStop = function()
        print("koko ----- timelineController_1 结束 -----")
        self.isTimeline_1_End = true
    end

    self.timelineController_2.OnTimelineStop = function()
        print("koko ----- timelineController_2 结束 -----")
        self.isTimeline_2_End = true
    end

    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = cs_coroutine.start(self.DelayInit, self)
end


function DreamSpace_StartStory:DelayInit() 


    cs_coroutine.yield_return( DreamSpaceStory.WaitInstance() ) -- 等待实例化
    self.dreamSpaceStory = DreamSpaceStory.GetInstance()   -- 拿到唯一实例

    --- 
    cs_coroutine.yield_return( DreamSpace_FullScreen.WaitInstance() ) -- 等待实例化
    self.dreamSpace_FullScreen = DreamSpace_FullScreen.GetInstance()   -- 拿到唯一实例
    --self.dreamSpace_FullScreen:SwitchToBlack( 1.0, true ) -- 瞬间黑屏
    self.dreamSpace_FullScreen:SwitchToTransparent( 1.0, true ) -- 瞬间透明

    local switchablePlayerControllerBH = nil
    for i = 1, DreamSpaceStates.DelayInitWaitFrames do
        self.vcam3rdPersonFollow = GlobalsInDreamSpace.FindComponent("vcam3rdPersonFollow") -- CinemachineVirtualCamera
        switchablePlayerControllerBH = GlobalsInDreamSpace.FindComponent("switchablePlayerControllerBH")
        if isNotNull(self.vcam3rdPersonFollow) and isNotNull(switchablePlayerControllerBH) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end
    if isNull(self.vcam3rdPersonFollow) or isNull(switchablePlayerControllerBH) then
        printError("始终没能找到 vcam3rdPersonFollow 或 switchablePlayerControllerBH, 请查找原因")
        return
    end
    self.switchablePlayerController = DreamSpaceLuaUtils.GetLuaScr(switchablePlayerControllerBH.gameObject, "Game.DreamSpace.CharacterController.SwitchablePlayerController" )
    assert( self.switchablePlayerController )
    ---
    cs_coroutine.yield_return( DreamSpace_Postprocessing.WaitInstance() ) -- 等待实例化
    self.dreamSpace_Postprocessing = DreamSpace_Postprocessing.GetInstance()   -- 拿到唯一实例

    self.isInit = true
end


function DreamSpace_StartStory:OnDestroy()
    DreamSpaceLuaUtils.StopCoroutine( self.co )
    self.co = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


-- ===============================================================

function DreamSpace_StartStory:Play() 
    -- 等待初始化成功:
    while self.isInit == false do
        coroutine.yield(Yielders.EndOfFrame)
    end


    -- =================================================================================== -- 

    ----- 入场黑屏, 等待一切就绪, 然后淡入:


    ----- 回忆模式的画面, vcam_1 视角,

    -- cut:
    self.vcam3rdPersonFollow.enabled = false
    self.vcam_1.enabled = true
    self.vcam_2.enabled = false

    -- 画面后处理效果: 回忆模式 
    self.dreamSpace_Postprocessing:SwitchToMemory(0.01)

    DreamSpaceSounds.Play( DreamSpaceSounds.music.dream )

    
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))

    
    print( "--- 黑屏开始淡出 ----" )

    -- 黑屏淡出
    -- self.dreamSpace_FullScreen:SwitchToTransparent( 5.0 )
    -- while self.dreamSpace_FullScreen:GetIsDirty() == true do
    --     coroutine.yield(Yielders.EndOfFrame)
    -- end
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 1.0 ))


    print( "--- 开始放故事 -1- ----" )
    cs_coroutine.yield_return( self.dreamSpaceStory:PlayStory( 1001 ) ) 


    -- 画面后处理效果: 正常 彩色 模式 
    self.dreamSpace_Postprocessing:SwitchToCommon( 20 )
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 2.0 ))

    
    self.electricalTrigger_2:CallWhenBeTriggerdFromInit()
    while self.isTimeline_2_End == false do
        coroutine.yield(Yielders.EndOfFrame)
    end

    print( "--- 结束 !!!!! ----" )

    self.vcam3rdPersonFollow.enabled = true
    self.vcam_1.enabled = false
    self.vcam_2.enabled = false


    coroutine.yield(Yielders.EndOfFrame)

    print( "--- 开始放故事 -2- ----" )
    cs_coroutine.yield_return( self.dreamSpaceStory:PlayStory( 1002 ) ) 


    ------ 人变猫:
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))
    self.switchablePlayerController:Switch(true)
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 2 ))


    ----------------
    DreamSpaceSounds.Stop( DreamSpaceSounds.music.dream )
end




return DreamSpace_StartStory
